from invoice import discounted_total
import unittest

class TestDiscount(unittest.TestCase):
    def test_1(self):
        self.assertEqual(discounted_total(20000, 10), 18000)
    def test_2(self):
        self.assertEqual(discounted_total(2500, 0), 2500)
